cd /workspace && node -e "
const XLSX = require('xlsx');
const { Document, Packer, Paragraph, Table, TableRow, TableCell, TextRun, WidthType, AlignmentType, BorderStyle, HeadingLevel } = require('docx');
const fs = require('fs');

// Read Excel data
const workbook = XLSX.readFile('testbed/data/product_inventory.xlsx');
const sheet = workbook.Sheets[workbook.SheetNames[0]];
const data = XLSX.utils.sheet_to_json(sheet);

// Table border style
const borders = {
  top: { style: BorderStyle.SINGLE, size: 1, color: '000000' },
  bottom: { style: BorderStyle.SINGLE, size: 1, color: '000000' },
  left: { style: BorderStyle.SINGLE, size: 1, color: '000000' },
  right: { style: BorderStyle.SINGLE, size: 1, color: '000000' },
};

// Header row
const headerRow = new TableRow({
  children: ['#', 'Product ID', 'Name', 'Category', 'Price', 'In Stock'].map(h =>
    new TableCell({
      borders,
      children: [new Paragraph({ children: [new TextRun({ text: h, bold: true, size: 22, font: 'Calibri' })], alignment: AlignmentType.CENTER })],
      shading: { fill: '2E75B6' },
      verticalAlign: 'center',
    })
  ),
});

// Data rows
const dataRows = data.map((row, i) =>
  new TableRow({
    children: [
      String(i + 1),
      row['Product ID'],
      row['Name'],
      row['Category'],
      '\$' + row['Price'],
      row['In Stock'],
    ].map((val, ci) =>
      new TableCell({
        borders,
        children: [new Paragraph({
          children: [new TextRun({ text: val, size: 20, font: 'Calibri', color: ci === 5 ? '2E7D32' : '000000' })],
          alignment: (ci === 0 || ci === 4 || ci === 5) ? AlignmentType.CENTER : AlignmentType.LEFT,
        })],
        shading: { fill: i % 2 === 0 ? 'F2F2F2' : 'FFFFFF' },
      })
    ),
  })
);

// Categories summary
const categories = {};
data.forEach(r => {
  const cat = r['Category'];
  categories[cat] = (categories[cat] || 0) + 1;
});
const catSummary = Object.entries(categories).map(([k, v]) => k + ' (' + v + ')').join(', ');
const prices = data.map(r => r['Price']);
const minPrice = Math.min(...prices);
const maxPrice = Math.max(...prices);
const mostExpensive = data.reduce((a, b) => a['Price'] > b['Price'] ? a : b);
const leastExpensive = data.reduce((a, b) => a['Price'] < b['Price'] ? a : b);

const doc = new Document({
  sections: [{
    properties: {},
    children: [
      // Title
      new Paragraph({
        children: [new TextRun({ text: 'Product Inventory Summary', bold: true, size: 36, font: 'Calibri', color: '1F4E79' })],
        heading: HeadingLevel.HEADING_1,
        alignment: AlignmentType.CENTER,
        spacing: { after: 200 },
      }),
      // Subtitle
      new Paragraph({
        children: [new TextRun({ text: 'Generated from: data/product_inventory.xlsx', italics: true, size: 20, font: 'Calibri', color: '666666' })],
        alignment: AlignmentType.CENTER,
        spacing: { after: 400 },
      }),
      // Overview heading
      new Paragraph({
        children: [new TextRun({ text: 'Overview', bold: true, size: 28, font: 'Calibri', color: '2E75B6' })],
        heading: HeadingLevel.HEADING_2,
        spacing: { before: 200, after: 200 },
      }),
      new Paragraph({ children: [new TextRun({ text: 'Total Products: ', bold: true, size: 22, font: 'Calibri' }), new TextRun({ text: String(data.length), size: 22, font: 'Calibri' })], spacing: { after: 80 } }),
      new Paragraph({ children: [new TextRun({ text: 'Price Range: ', bold: true, size: 22, font: 'Calibri' }), new TextRun({ text: '\$' + minPrice + ' – \$' + maxPrice, size: 22, font: 'Calibri' })], spacing: { after: 80 } }),
      new Paragraph({ children: [new TextRun({ text: 'Most Expensive: ', bold: true, size: 22, font: 'Calibri' }), new TextRun({ text: mostExpensive['Name'] + ' (\$' + mostExpensive['Price'] + ')', size: 22, font: 'Calibri' })], spacing: { after: 80 } }),
      new Paragraph({ children: [new TextRun({ text: 'Least Expensive: ', bold: true, size: 22, font: 'Calibri' }), new TextRun({ text: leastExpensive['Name'] + ' (\$' + leastExpensive['Price'] + ')', size: 22, font: 'Calibri' })], spacing: { after: 80 } }),
      new Paragraph({ children: [new TextRun({ text: 'Categories: ', bold: true, size: 22, font: 'Calibri' }), new TextRun({ text: catSummary, size: 22, font: 'Calibri' })], spacing: { after: 200 } }),
      // In Stock note
      new Paragraph({
        children: [
          new TextRun({ text: '✅ Note: ', bold: true, size: 22, font: 'Calibri', color: '2E7D32' }),
          new TextRun({ text: 'All 20 listed items are marked as \"In Stock\" with a status of \"Yes\".', size: 22, font: 'Calibri', color: '2E7D32' }),
        ],
        spacing: { after: 400 },
      }),
      // Table heading
      new Paragraph({
        children: [new TextRun({ text: 'Product Details', bold: true, size: 28, font: 'Calibri', color: '2E75B6' })],
        heading: HeadingLevel.HEADING_2,
        spacing: { before: 200, after: 200 },
      }),
      // Table
      new Table({
        rows: [headerRow, ...dataRows],
        width: { size: 100, type: WidthType.PERCENTAGE },
      }),
      // Footer note
      new Paragraph({
        children: [new TextRun({ text: 'Note: The product \"AUTUMN10 Cart Discount\" (\$0) appears to be a promotional/discount entry rather than a physical product.', italics: true, size: 18, font: 'Calibri', color: '999999' })],
        spacing: { before: 300 },
      }),
    ],
  }],
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('data/product_inventory_summary.docx', buffer);
  console.log('Document saved successfully to data/product_inventory_summary.docx');
  console.log('File size: ' + (buffer.length / 1024).toFixed(1) + ' KB');
});
"
